/* O mesmo execício anterio, mas agora não será informado o número de mercadoria em estoque.
Então o funcionamento devserá ser da seguinte forma: ler o valor da mercadoria e perguntar 'MAIS
MERCADORIA(S/N)'. Ao final, imprimir o valor total em estoque e a média de valor da mercadoria  
 */

#include <iostream>
#include <vector>
#include <cstdio>

void MediaMercadoria(float * pVector, int tamanho);

int main()
{
//objeto vector vMecadoria do tipo float

    std::vector<float>vMercadoria;
    char resposta;
    int i = 0;
    float valor;

    std::cout << "compre sua mercadorias aqui\n\n";
//faça...
    do{
        std::cout <<  "digite o valor da mercadoria: ";
        std::cin >> valor;
        
        vMercadoria.push_back(valor);

        std::cout << "MAIS MERCADORIA?(S/N) ";
        std::cin >> resposta;

       if(resposta == 'n')
        {
            std::cout << "vamo ver o valor total e a media ";
        }
        system("CLS");
//reposta for diferente de 's' o loop vai ser executado mais uma vez.

    }while(resposta =='s');
    
    int tamanho = vMercadoria.size();
//vector::data(): essa função método retorna o primeiro byte do objeto vector alocado na memória RAM
    std::cout << vMercadoria.data() << std::endl;
//função de tipo void vai receber em seu parâmetro ponteiro o primeiro byte do objeto vector alocado na memoria ram e tamanho dela
//para percorre os elementos alocados contígua na memória.
    MediaMercadoria(vMercadoria.data(), tamanho);   




    return 0;
}


void MediaMercadoria(float * pVector, int tamanho)
{

    float media{0.0f}, totValor{0.0f};
//Será exibido na tela o primeiro byte do vector que também é o endereço do seu primeiro elemento
    std::cout << pVector << std::endl; 
//tamanho quantos elemento vector
    for(int i = 0; i < tamanho; i ++)
    {
        //Variável acomuladora media que vai somar o valor dos elementos do vector que foi passado para o ponteiro que faz referência.
        //i: nossa variável contadora que vai percorrer cada elemento do vector.
        //Para percorrer os elementos tem que saber o primeiro byte  do próximo elemento  a partir do primeiro. Logo temos o um aritmética de ponteiros,
        //o i vai ser multiplicado pelo tamanho(que é float) e vai somar ao seu primeiro endereço. Logo teremos o primeiro byte do próximo elemento
        //que será lido seu valor e somado à variável acomuladora chamada rotulada como media.
        media += *(pVector + i); 

    }

    totValor = media;
    media = media / tamanho;

    std::cout << "\nTotal do valor da mercadoria em estoque: " << totValor;
    std::cout << "\nMédia do valor  da mercadoria em estoque: " << media << std::endl;   
}

