        //Vector::back(): Essa função método acesso o último elemento do objeto vector. Logo o último valor acesso pela back 
        //vai ser testado na estrutura condicional.
        //Se vNum.back() maior que 0 então faça
        if(vNum.back() > 0){
            //nossa variável contadora, ela vai contar quantos números positivos tem
            totPositivo++;
        //se não se vNum.back()(retornado o último valor acessado pela vector::back()) menor que 0 então faça
        }else if(vNum.back() < 0){
            //nossa variável contadora, ela vai contar quantos números negativos tem
            totNegativo++;
        }
        //Nossa variável contadora vai ser incrementada enquanto vNum for diferene de vazio
        i++;
        //vector::pop_back: delete last element(deleta o último elemento do vector), assim o vector vai diminuindo de tamanho até ficar vazio.
        //Cada elemento do vector vai ser destruídos até que não possua nem um  
        vNum.pop_back();
    }
//Será imprimido na tela quantidade de números  negativos e positivo dos dez números digitados pelo o usuário 
    std::cout << "\nQuantidade numero positivo: " << totPositivo;
    std::cout << "\nQuantidade numero negativos: " << totNegativo;


    return 0;
}

