#include <iostream>
#include <locale>

//Essa função tem um Array e vai receber como argumento o Array vNum[] local da main()
//essa vNum[] dessa função vai receber o primeiro endereço que é o primeiro elemento de vNum[] da main()
//sendo assim, esse array local dessa função pode ler os valores mas, devemos indicar explicitamente o
//endereço de cada elemento vai ser lido
// Só o nome do vetor vai está passando o primeiro endereço que também onde começa o elemento '0' que
//estão carregados na memória RAM;
void MaiorNumero(int vNum[]);

using namespace std;
int main()
{
    setlocale(LC_ALL, "portuguese");
    //Variável vetor é um tipo de variável ponteiro que tem vários compartimentos um do lado do outro(contígua)
    // e podendo armazenar dados.
    //Para sabe o valor que está armazenando devemos informar o seu índice entre colchetes, ao ìnfomar qual compartimento
    //que queremos ver o valor ou armazenar.
    //Quando criamos um array entre seus colchetes [] indicamos o seu tamanho, quantos compartimentos terá. Lembrando que
    //o seu primeiro índice é 0 então  de 0 á 4 temo 5 compartimentos e todos podem armazenar  ou serem lidos.

    int vNum[3] {0};//variável vetor inicializamos todos compartimentos com 0 para não guardar lixo(valore aleatórios)

    cout << "Entre com primeiro número: ";
    cin >> vNum[0];
    cout << "\nEntre com segundo número: ";
    cin >> vNum[1];
    cout << "\nEntre com terceiro número: ";
    cin >> vNum[2];

    //função que recebe um vetor
    //está sendo enviado o seu primeiro endereço
    MaiorNumero(vNum);

    system("pause");
    return 0;
}

void MaiorNumero(int vNum[])
{

    //usando a estrutura condicional ternário
    //Essa estutura vai verificar se vNum[0] é maior que vNum[1]
    // ? isso significa que estamos fazendo um pergunta ao compilador para que ele retorne um dos valores
    // se o vNum[0] for maior que vNum[1] ? vai atribuir o valor de vNum[0] a variável qualMaior
    //Na linha 41 acontece a mesma coisa.
    int qualMaior = vNum[0] > vNum[1] ? vNum[0] : vNum[1];
    int maior =  qualMaior > vNum[2] ? qualMaior : vNum[2];
    //Se o qualMaior for maior que vNum[2] ? o qualMaior vai ser atribuir do ao Maio, caso ao contrario vai ser o vNum[2]

    if(maior  == vNum[0]){
        //cout << "Maior número é o Num1: " << maior << endl;
        //Como um vetor(array) é um tipo de ponteiro podemos fazer  indireção  usando o asterisco ( ' * ' ) .
        cout << *(vNum + 0) << endl;  // vai funcionar do mesmo jeito
        //Nesse caso ele  vai estar fazendo uma aritmética pelo tipo do array
        // o zero vai ser multiplica pelo 4 bytes então ele é zero vezes o 4
        //O processador vai ler o primeiro endereço que é do tipo int e sabe que falta 3 endereços(bytes)e ainda
        // para serem percorrido para que possa ler o seu valor ou atribuir. Nesse caso é para ser lido
