            total_eleitores = sc.nextInt();

            System.out.print("\nDIGITE O NÚMERO VÁLIDO DE VOTOS (00 PARA SAIR): ");
            votos_validos = sc.nextInt();

            if(votos_validos == 0) {
                System.out.println("VOCÊ SAIU");
                break;
            }

            System.out.print("\nDIGITE O NÚMERO DE VOTOS NULOS (00 PARA SAIR): ");
            votos_nulos = sc.nextInt();

            if(votos_nulos == 0) {
                System.out.println("VOCÊ SAIU");
                break;
            }

            System.out.print("\nDIGITE O NÚMERO DE VOTOS BRANCOS (00 PARA SAIR): ");
            votos_brancos = sc.nextInt();

            if(votos_brancos == 0) {
                System.out.println("VOCÊ SAIU");
                break;
            }

            if (votos_validos + votos_nulos + votos_brancos > total_eleitores) {
                System.out.println("A SOMA DOS VOTOS VÁLIDOS, NULOS E BRANCOS NÃO PODE SER MAIOR QUE O TOTAL DE ELEITORES!");
                break;
            }

            double percentual_votos_brancos = ((double)votos_brancos / total_eleitores) * 100;
            double percentual_votos_nulos = ((double)votos_nulos / total_eleitores) * 100;
            double percentual_votos_validos = ((double)votos_validos / total_eleitores) * 100;

