            System.out.printf("\tPERCENTUAL DE VOTOS NULOS: %.2f%%%n", percentual_votos_nulos);
            System.out.printf("\tPERCENTUAL DE VOTOS VÁLIDOS: %.2f%%%n", percentual_votos_validos);
        }

        sc.close();
